create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role text not null default 'staff' check(role in('admin','manager','case_worker','finance','staff')),active boolean not null default true,created_at timestamptz default now());
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and active=true)$$;
create table if not exists public.programmes(id uuid primary key default gen_random_uuid(),title text not null,category text,description text,status text default 'active',start_date date,end_date date,created_at timestamptz default now());
create table if not exists public.partners(id uuid primary key default gen_random_uuid(),name text not null,partner_type text,contact_name text,email text,phone text,contribution text,status text default 'prospect',notes text,created_at timestamptz default now());
create table if not exists public.events(id uuid primary key default gen_random_uuid(),title text not null,description text,venue text,starts_at timestamptz,ends_at timestamptz,status text default 'planned',created_at timestamptz default now());
create table if not exists public.outreach_activities(id uuid primary key default gen_random_uuid(),title text not null,activity_date date,location text,participants integer default 0,programme_id uuid references public.programmes(id),notes text,created_at timestamptz default now());
create table if not exists public.volunteer_applications(id uuid primary key default gen_random_uuid(),full_name text not null,email text not null,interest_area text not null,availability text,experience text,consent boolean not null,status text default 'received',created_at timestamptz default now());
create table if not exists public.contact_messages(id uuid primary key default gen_random_uuid(),full_name text not null,email text not null,topic text,message text not null,consent boolean not null,status text default 'new',created_at timestamptz default now());
create table if not exists public.donation_intents(id uuid primary key default gen_random_uuid(),donor_name text not null,email text not null,amount_ugx bigint not null check(amount_ugx>=1000),message text,status text default 'new',created_at timestamptz default now());
create table if not exists public.donations(id uuid primary key default gen_random_uuid(),donor_name text,donor_email text,amount numeric(14,2) not null,currency text default 'UGX',provider text,provider_reference text unique,status text default 'pending',received_at timestamptz,created_at timestamptz default now());
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),description text not null,category text,amount numeric(14,2) not null,currency text default 'UGX',expense_date date default current_date,reference text,recorded_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.beneficiaries(id uuid primary key default gen_random_uuid(),case_code text unique not null,display_name text not null,consent_recorded boolean not null default false,assigned_to uuid references auth.users(id),case_status text default 'open',referral_status text,created_at timestamptz default now());
create table if not exists public.case_notes(id uuid primary key default gen_random_uuid(),beneficiary_id uuid references public.beneficiaries(id) on delete cascade,note text not null,sensitivity text default 'restricted',created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.audit_logs(id bigint generated always as identity primary key,actor uuid references auth.users(id),action text not null,entity text not null,entity_id text,created_at timestamptz default now());
do $$ declare t text; begin foreach t in array array['profiles','programmes','partners','events','outreach_activities','volunteer_applications','contact_messages','donation_intents','donations','expenses','beneficiaries','case_notes','audit_logs'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy %I on public.%I for select to authenticated using(public.is_staff())','staff_read_'||t,t); execute format('create policy %I on public.%I for insert to authenticated with check(public.is_staff())','staff_insert_'||t,t); execute format('create policy %I on public.%I for update to authenticated using(public.is_staff()) with check(public.is_staff())','staff_update_'||t,t); end loop; end $$;
create policy public_volunteer_insert on public.volunteer_applications for insert to anon,authenticated with check(consent=true);
create policy public_contact_insert on public.contact_messages for insert to anon,authenticated with check(consent=true);
create policy public_donation_intent_insert on public.donation_intents for insert to anon,authenticated with check(amount_ugx>=1000);
-- After creating a trusted Auth user, grant admin by inserting their UUID into public.profiles. Tighten casework policies by role before real sensitive data is entered.